// Confirmado contra um payload real de Workflow Webhook do GHL em 18/set/2026:
// o corpo vem achatado (contact_id, first_name, email, phone, tags como string
// unica, location, workflow), com um 'contact' aninhado que so tem
// attributionSource/lastAttributionSource -- o 'attributionSource' solto no
// topo do body vem sempre vazio ({}), o de verdade fica em contact.attributionSource.
// Nenhuma decisao de negocio acontece aqui: so molda o payload cru no formato
// que integracao.fila_sync espera. Casamento de contato, dono do campo e
// deteccao de eco ficam todos em SQL (ver sql/integracao/integracao.sql).
//
// NAO tem etapa_funil_marketing aqui de proposito: confirmado em 16/set/2026
// que pipeline/etapa pertence a Oportunidade no GHL, nao ao Contato -- nao
// existe esse campo pra ler, nem de webhook nem de busca.
//
// tipo_evento usa o nome do Workflow do GHL que disparou (hoje so tem um
// gatilho, Tag de contato) -- se no futuro esse mesmo workflow ganhar mais
// gatilhos, vai precisar de um jeito melhor de distinguir.
const body = $json.body ?? $json;

return {
  json: {
    origem: 'ghl',
    tipo_evento: body.workflow?.name ?? 'desconhecido',
    telefone_bruto: body.phone ?? null,
    email_bruto: body.email ?? null,
    cpf_bruto: null, // GHL normalmente nao guarda CPF; ajustar se houver custom field
    campos: {
      id_contato_ghl: body.contact_id ?? null,
      tags: body.tags ?? null,
      origem_campanha: body.contact?.attributionSource ?? null,
    },
  },
};

