// Confirmado contra uma resposta real do GET (node 'Buscar lead CVCRM') em
// 18/set/2026: a resposta vem envelopada em {codigo, total, leads: [...]},
// nao o lead direto -- e dentro do lead, 'situacao' e 'corretor' sao objetos
// {id, nome[, email]}, nao campos escalares.
// tipo_evento nao vem em lugar nenhum do payload do CVCRM (o webhook so manda
// idlead) -- se for preciso distinguir o gatilho (criacao vs. mudanca de
// situacao), a saida e cadastrar um Webhook por gatilho no painel do CVCRM,
// cada um com uma query string diferente na URL (ex.: ?gatilho=criacao),
// e ler isso do node 'Webhook CVCRM' original, nao deste.
// TODO: 'empreendimento' veio como array vazio no lead de teste (sem nenhum
// empreendimento vinculado) -- confirmar o formato dos itens (id/nome) contra
// um lead real que tenha empreendimento antes de confiar nesse mapeamento.
//
// origem_campanha invertido em 21/set/2026: quem gerencia campanha e origem
// de lead e o CVCRM, nao o GHL, entao o dono passou a ser cvcrm (ver
// dono_campo). O 'origem' do lead CVCRM ja e uma lista fechada de valores
// padronizados (Facebook, Google, Portais, Painel Gestor etc.), entao o
// valor passa direto pro GHL, sem de-para -- o GHL aceita texto livre.
//
// situacao_lead removido daqui em 22/set/2026, RECOLOCADO em 23/set/2026
// como situacao_cvcrm: a inversao de 22/set tinha deixado a sincronizacao
// de situacao so de mao unica (GHL->CVCRM), contra o objetivo do projeto
// (bidirecional de verdade -- alterar em qualquer lado reflete no outro).
// lead.situacao.id ja' e' o idsituacao_cvcrm direto, sem precisar de
// de-para nessa ponta (o de-para por nome so' e' necessario na direcao
// contraria, GHL->CVCRM, porque o webhook do GHL manda o nome da etapa em
// texto, nao um id). Ver dono_campo pro desenho completo (campo_destino
// 'situacao_ghl' e' marcador especial, tratado a parte do PUT customFields
// normal).
//
// interacao_cvcrm adicionado 23/set/2026, corrigido no mesmo dia: o gatilho
// dedicado "Nova interacao" do CVCRM nao dispara de verdade (confirmado ao
// vivo -- varias anotacoes de teste, nenhum webhook chamado). A interacao
// mais recente vem de carona em QUALQUER outro gatilho que ja funciona
// (Associar Atendente, mudanca de situacao), porque esta busca sempre traz o
// lead inteiro. Por isso manda tambem interacao_cvcrm_id (o id da ultima
// interacao, assumindo ordem cronologica crescente no array -- observado nos
// testes, nunca confirmado formalmente que e' sempre assim): e' contra esse
// id que o trigger preencher_fila_sync (ver integracao.sql) decide se essa
// interacao ja foi vista antes, pra nao reenviar a mesma nota antiga toda
// vez que outro campo mudar.
//
// tarefa_cvcrm/visita_cvcrm corrigido 24/set/2026 (segunda volta): a versao
// de 23/set usava lead.tarefa embutido (sem chamada extra), mas esse array
// nao tem campo de tipo -- impossivel distinguir Visita de Tarefa generica
// so' com ele. Voltou a usar o endpoint CVDW /leads/tarefas (node 'Buscar
// tarefa CVCRM'), que tem tipo_interacao (V=Visita, L=Ligacao, T=Tarefa,
// W=WhatsApp, A=Anotacao) -- dessa vez com motivo real, nao so' porque um
// gatilho manda idtarefa. Sem filtro server-side por idlead, filtra aqui
// client-side e pega a mais recente (por idtarefa) desse lead. Visita e
// Tarefa compartilham o MESMO id sequence (idtarefa), entao usam o MESMO
// campo de controle pra dedup (tarefa_cvcrm_id) mesmo quando o destino e'
// visita_cvcrm -- so' uma das duas (tarefa_cvcrm OU visita_cvcrm) vem
// preenchida por vez, conforme o tipo da mais recente.
const lead = ($('Buscar lead CVCRM').item.json.leads ?? [])[0] ?? {};
const interacoes = lead.interacao ?? [];
const ultimaInteracao = interacoes.length ? interacoes[interacoes.length - 1] : null;
const tarefasDoLead = ($('Buscar tarefa CVCRM').item.json.dados ?? []).filter((t) => t.idlead === lead.idlead);
const ultimaTarefa = tarefasDoLead.length
  ? tarefasDoLead.reduce((a, b) => (a.idtarefa > b.idtarefa ? a : b))
  : null;
const ehVisita = ultimaTarefa?.tipo_interacao === 'V';

return {
  json: {
    origem: 'cvcrm',
    tipo_evento: $('Webhook CVCRM').item.json.query?.gatilho ?? 'desconhecido',
    telefone_bruto: lead.telefone ?? null,
    email_bruto: lead.email ?? null,
    cpf_bruto: lead.documento_tipo === 'cpf' ? (lead.documento ?? null) : null,
    campos: {
      idlead_cvcrm: lead.idlead ?? null,
      corretor_responsavel: lead.corretor?.nome ?? null,
      empreendimento_interesse: lead.empreendimento?.[0]?.nome ?? null,
      origem_campanha: lead.origem ?? null,
      interacao_cvcrm: ultimaInteracao?.descricao ?? null,
      interacao_cvcrm_id: ultimaInteracao?.id ?? null,
      situacao_cvcrm: lead.situacao?.id ?? null,
      tarefa_cvcrm_id: ultimaTarefa?.idtarefa ?? null,
      tarefa_cvcrm: (ultimaTarefa && !ehVisita) ? {
        nome: ultimaTarefa.descricao,
        data: ultimaTarefa.data,
        concluida: ultimaTarefa.situacao === 'C',
      } : null,
      visita_cvcrm: (ultimaTarefa && ehVisita) ? {
        titulo: ultimaTarefa.descricao,
        data: ultimaTarefa.data,
      } : null,
    },
  },
};

