// Recebe a saida de sucesso ou erro de qualquer um dos dois HTTP Request (CVCRM
// ou GHL). O contexto da linha da fila (fila_sync_id, contato_id, hash, campos
// enviados) nao sobrevive a chamada HTTP, entao volta a ser lido do no anterior
// ao envio, igual ao padrao ja usado em automacao_reporting/workflow_n8n.json.
const origem = $('Canal destino').item.json;
const deuErro = Boolean($json.error);

return {
  json: {
    fila_sync_id: origem.fila_sync_id,
    contato_id: origem.contato_id,
    destino: origem.destino,
    campos_permitidos: origem.campos_permitidos,
    hash_evento: origem.hash_evento,
    status: deuErro ? 'erro' : 'enviado',
    detalhe: deuErro ? String($json.error?.message ?? 'erro desconhecido').slice(0, 1000) : null,
  },
};

// Corrigido 23/set/2026: o webhook de oportunidade ja manda telefone/email/tags
// no corpo (mesmo formato do Webhook GHL de contato) -- nao precisa buscar o
// contato à parte. So a situacao precisa de traducao (node anterior).
const body = $('Webhook GHL Oportunidade').item.json.body ?? $('Webhook GHL Oportunidade').item.json;
const idsituacao = $json.idsituacao_cvcrm ?? null;

return {
  json: {
    origem: 'ghl',
    tipo_evento: 'oportunidade_estagio_alterado',
    telefone_bruto: body.phone ?? null,
    email_bruto: body.email ?? null,
    cpf_bruto: null,
    campos: {
      situacao_lead: idsituacao,
    },
  },
};

